mapper.delete:
DELETE FROM credential_file
WHERE file_id IN

    #{id}

mapper.select:
SELECT COUNT(*)
FROM credential_file
WHERE original_file_path = #{originalFilePath}
  AND file_id <> #{fileId}
  AND deleted_at IS NULL

SELECT COUNT(*)
FROM credential_file
WHERE markdown_file_path = #{markdownFilePath}
  AND file_id <> #{fileId}
  AND deleted_at IS NULL

mapper.update:
UPDATE credential_file
SET markdown_file_path = #{markdownFilePath}
WHERE file_id = #{fileId}
  AND convert_status = 'CONVERTING'
  AND deleted_at IS NULL
  AND deletion_status IS NULL

UPDATE credential_file
SET deleted_at = #{deletedAt}
WHERE file_id = #{fileId}
  AND deleted_at IS NULL
  AND deletion_status = 'DELETING'

UPDATE credential_file
SET deletion_status = 'FAILED',
    deletion_failed_stage = #{stage},
    deletion_error_message = #{errorMessage}
WHERE file_id = #{fileId}
  AND deletion_status = 'DELETING'
